public class CombatProbePlugin:Plugin {public override string Name=>"MZLocalCombatProbe";public override string Description=>"Local automated probe only";public override string Author=>"MZ tests";public override Version Version=>new Version(1,0);public override Version RequiredApiVersion=>new Version(1,1,7);public override void Enable(){}public override void Disable(){}}
[CommandHandler(typeof(GameConsoleCommandHandler))]
public class CombatProbeCommand:ICommand {
 public string Command=>"mzcombattest";public string[] Aliases=>new string[0];public string Description=>"Local test only";
 static int spawnIndex;static readonly List<ReferenceHub> bots=new List<ReferenceHub>();static readonly JArray checks=new JArray(),events=new JArray();static MzPlugin M=>MzPlugin.Instance;
 static void Check(bool ok,string name){checks.Add(new JObject{["name"]=name,["pass"]=ok});if(!ok)throw new Exception(name);}
 static ReferenceHub Spawn(string name,RoleTypeId role){var h=bots[spawnIndex++];h.nicknameSync.MyNick="MZTest_"+name;Role(h,role);return h;}
 static void Role(ReferenceHub h,RoleTypeId role){var p=Player.Get(h);p.SetRole(role,RoleChangeReason.RemoteAdmin,RoleSpawnFlags.None);p.IsGodModeEnabled=false;h.playerEffectsController.DisableAllEffects();p.Health=p.MaxHealth;p.HumeShield=0;p.ArtificialHealth=0;}
 static void Hit(ReferenceHub v,DamageHandlerBase h){Check(v.playerStats.DealDamage(h),"real DealDamage "+h.GetType().Name);}
 static JObject Last(string icon){var a=M.Combat.Ledger.Snapshot(M.Combat.Now);Check(a.Count>0,"death emitted "+icon);var e=(JObject)a.Last;Check(e.Value<string>("icon")==icon,"method "+icon);events.Add(e.DeepClone());return e;}
 static void Reset(){M.Combat.Reset();}
 static void Set(object obj,string key,object value){for(var t=obj.GetType();t!=null;t=t.BaseType){var f=t.GetField(key,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic);if(f!=null){f.SetValue(obj,value);return;}var p=t.GetProperty(key,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic);if(p!=null){p.SetValue(obj,value,null);return;}}throw new Exception(key);}
 static object Call(object obj,string name,params object[] args)=>obj.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(obj,args);
 static bool Has(ReferenceHub v,string icon)=>M.Combat.Ledger.Assists(CombatCapture.Person(v),null,M.Combat.Now).Any(a=>a["icons"].Any(i=>i.ToString()==icon));
 static void Extension(){
  checks.Clear();events.Clear();foreach(var bot in bots)Role(bot,RoleTypeId.Spectator);
  var a=bots[0];var b=bots[1];var target=bots[2];Role(a,RoleTypeId.NtfSergeant);Role(b,RoleTypeId.NtfSergeant);Role(target,RoleTypeId.Scp939);
  a.nicknameSync.MyNick="Alpha";b.nicknameSync.MyNick="Bravo";target.nicknameSync.MyNick="Shade";
  Check(M.Combat.HookCount==26,"26 hooks loaded");Reset();
  var jb=(InventorySystem.Items.Jailbird.JailbirdItem)Player.Get(a).AddItem(ItemType.Jailbird).Base;Set(jb,"_charging",true);
  var hitbox=((PlayerRoles.FirstPersonControl.IFpcRole)target.roleManager.CurrentRole).FpcModule.CharacterModelInstance.Hitboxes[0];
  Check(jb.ApplyDamage(a,hitbox,1,Vector3.forward,true),"real Jailbird charge hit");Check(Has(target,"item:Jailbird"),"Jailbird flash attributed to attacker");Check(!Has(target,"human-flash"),"not shown as grenade flash");
  target.playerEffectsController.GetEffect<Flashed>().ServerDisable();var now=M.Combat.Now;Check(M.Combat.Ledger.Assists(CombatCapture.Person(target),null,now+4.9).Count==1,"Jailbird grace at 4.9s");Check(M.Combat.Ledger.Assists(CombatCapture.Person(target),null,now+5.1).Count==0,"Jailbird expires after 5s");
  Reset();Player.Get(target).Position=new Vector3(0,1000,0);var grenade=UnityEngine.Object.Instantiate(Resources.FindObjectsOfTypeAll<InventorySystem.Items.ThrowableProjectiles.ExplosionGrenade>().First());
  Set(grenade,"_playerDamageOverDistance",AnimationCurve.Constant(0,100,1));Set(grenade,"_effectDurationOverDistance",AnimationCurve.Constant(0,100,1));
  typeof(InventorySystem.Items.ThrowableProjectiles.ExplosionGrenade).GetMethod("ExplodeDestructible",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{hitbox,new Footprint(a),hitbox.CenterOfMass+Vector3.up*.1f,grenade,ExplosionType.Jailbird});
  Check(target.playerEffectsController.GetEffect<Burned>().IsEnabled,"actual Jailbird explosion burn");Check(Has(target,"human-burn"),"Jailbird uses common burn attribution");UnityEngine.Object.Destroy(grenade.gameObject);
  Reset();Hit(target,new ExplosionDamageHandler(new Footprint(a),Vector3.zero,10000,100,ExplosionType.Cola));Last("item:SCP207");
  Reset();Hit(a,new ExplosionDamageHandler(new Footprint(a),Vector3.zero,10000,100,ExplosionType.Cola));var self=M.Combat.Ledger.Snapshot(M.Combat.Now).Last;Check(self.Value<bool>("suicide")&&self.Value<string>("icon")=="item:SCP207","cola self explosion uses cola icon");events.Add(self.DeepClone());
  Role(a,RoleTypeId.NtfSergeant);Role(target,RoleTypeId.Scp939);Reset();var gun=(Firearm)Player.Get(a).AddItem(ItemType.GunSCP127).Base;gun.TryGetModule<InventorySystem.Items.Firearms.Modules.Scp127.Scp127Hitscan>(out var hitscan);Hit(target,(DamageHandlerBase)Call(hitscan,"GetHandler",10000f));Last("item:GunSCP127");
  var snapshot=M.Collector.Players(true).First(p=>p.Value<uint>("networkId")==a.netId);Check(snapshot["special"].Any(x=>x[0].ToString()=="GunSCP127"),"127 in production special inventory data");
  Role(target,RoleTypeId.Scp939);Reset();Player.Get(a).Position=new Vector3(0,1000,0);Player.Get(b).Position=new Vector3(2,1000,0);Player.Get(target).Position=new Vector3(0,1000,8);
  var glasses=a.playerEffectsController.GetEffect<Scp1344>();glasses.IsEnabled=true;Call(glasses,"UpdateVision",true);Check(Has(target,"item:SCP1344"),"actual 1344 validated observer captured");
  var glassesB=b.playerEffectsController.GetEffect<Scp1344>();glassesB.IsEnabled=true;Call(glassesB,"UpdateVision",true);Check(M.Combat.Ledger.Assists(CombatCapture.Person(target),null,M.Combat.Now).Count==2,"two actual xray observers");
  glasses.ServerDisable();var detected=target.playerEffectsController.GetEffect<Scp1344Detected>();Call(detected,"UpdateStatus");now=M.Combat.Now;var remaining=M.Combat.Ledger.Assists(CombatCapture.Person(target),null,now+10.1);Check(remaining.Count==1&&remaining[0].Value<string>("name")=="Bravo","one observer stops: independent 10s expiry");
  Player.Get(target).Position=new Vector3(1000,1000,0);Call(glassesB,"UpdateVision",true);Call(detected,"UpdateStatus");now=M.Combat.Now;Check(M.Combat.Ledger.Assists(CombatCapture.Person(target),null,now+9.9).Count==2,"xray post-effect grace");Check(M.Combat.Ledger.Assists(CombatCapture.Person(target),null,now+10.1).Count==0,"xray expires after 10s");
  Check(M.Combat.Errors==0,"no capture errors");File.WriteAllText("combat-extension.json",new JObject{["ok"]=true,["checks"]=checks,["events"]=events}.ToString());
 }
 public bool Execute(ArraySegment<string> args,ICommandSender sender,out string response){
