   }
   if(args.Count>0&&args.Array[args.Offset]=="prepare"){for(int j=0;j<9;j++)Role(bots[j],j<6?RoleTypeId.Scientist:j==6?RoleTypeId.Scp173:j==7?RoleTypeId.Scp939:RoleTypeId.Scp049);var ow=bots[9];Role(ow,RoleTypeId.Spectator);Player.Get(ow).IsOverwatchEnabled=true;M.Match.Reset();M.Match.Tick(M.Collector.Players(true),0,true);File.WriteAllText("combat-pair.json",new JObject{["code"]=M.Pair(Player.Get(ow))}.ToString());response="6+3 test fixture paired";return true;}
