   if(args.Count>0&&args.Array[args.Offset]=="pair") {var ow=Spawn("Observer",RoleTypeId.Spectator);Player.Get(ow).IsOverwatchEnabled=true;File.WriteAllText("combat-pair.json",new JObject{["code"]=M.Pair(Player.Get(ow))}.ToString());response="Local pair file ready";return true;}
   checks.Clear();events.Clear();Check(M.Combat.HookCount==26,"26 production hooks loaded");
   var human=Spawn("Human",RoleTypeId.Scientist);var dog=Spawn("Dog",RoleTypeId.Scp939);var doc=Spawn("Doctor",RoleTypeId.Scp049);var gunner=Spawn("Gunner",RoleTypeId.NtfSergeant);var victim=Spawn("ScpVictim",RoleTypeId.Scp173);
