   Role(human,RoleTypeId.Scientist);Reset();Hit(human,new Scp939DamageHandler((Scp939Role)dog.roleManager.CurrentRole,35,Scp939DamageType.Claw));Player.Get(human).Health=Player.Get(human).MaxHealth;Hit(human,new Scp049DamageHandler(doc,-1,Scp049DamageHandler.AttackType.Instakill));Check(Last("049-touch")["assists"].Count()==0,"real full HP setter clears damage assist");
