   Role(human,RoleTypeId.Scientist);Reset();Hit(human,new UniversalDamageHandler(1000,DeathTranslations.Falldown));Check(M.Combat.Ledger.Snapshot(M.Combat.Now)[0].Value<bool>("suicide"),"real environmental self death");
   Role(human,RoleTypeId.Scientist);Reset();Role(human,RoleTypeId.Spectator);Check(M.Combat.Ledger.Snapshot(M.Combat.Now).Count==0,"admin role change not kill");Check(M.Combat.Errors==0,"zero capture errors");
   Role(victim,RoleTypeId.Scp173);Reset();Player.Get(gunner).Position=new Vector3(0,1000,0);var a7=(Firearm)Player.Get(gunner).AddItem(ItemType.GunA7).Base;a7.TryGetModule<InventorySystem.Items.Firearms.Modules.A7BurnEffectModule>(out var burn);Player.Get(victim).Position=gunner.transform.position+gunner.PlayerCameraReference.forward*Convert.ToSingle(CombatCapture.Read(burn,"_forwardOffset"));Call(burn,"OnFired");Check(victim.playerEffectsController.GetEffect<Burned>().IsEnabled,"actual A7 applies burn");Check(Has(victim,"human-burn"),"A7 burn source captured");victim.playerEffectsController.GetEffect<Burned>().ServerDisable();Check(Has(victim,"human-burn"),"disabled burn retains grace");
